/* Hallmark · component: featured company card · genre: modern-minimal · theme: Warm Horizon
 * states: default · hover · focus · active · disabled · loading · error · success
 * Hallmark · pre-emit critique: P5 H5 E5 S5 R5 V5
 */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.visa-results {
  display: grid;
  gap: var(--space-sm);
}

.visa-results-head {
  display: grid;
  gap: var(--space-sm);
  align-items: end;
}

.visa-results-title {
  display: flex;
  min-width: 0;
  align-items: flex-start;
  gap: var(--space-sm);
}

.visa-results-title > div {
  min-width: 0;
}

.visa-results-title h2,
.visa-featured-copy h3 {
  min-width: 0;
  overflow-wrap: anywhere;
}

.visa-results-title p {
  margin-top: var(--space-3xs);
  color: var(--text-secondary);
  font-size: 0.875rem;
  line-height: 1.6;
}

.visa-results-status,
.visa-results-state-icon {
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  width: 2.75rem;
  height: 2.75rem;
  border: var(--rule-width) solid var(--color-rule);
  border-radius: var(--radius-pill);
  background: var(--accent-green-soft);
  color: var(--accent-green);
}

.visa-results-status svg,
.visa-results-state-icon svg {
  width: 1.25rem;
  height: 1.25rem;
}

.visa-results-board-link,
.visa-featured-primary,
.visa-featured-secondary {
  display: inline-flex;
  min-height: 2.75rem;
  align-items: center;
  justify-content: center;
  gap: var(--space-2xs);
  border-radius: var(--radius-button);
  white-space: nowrap;
  font-weight: 700;
  cursor: pointer;
}

.visa-results-board-link {
  width: fit-content;
  padding-inline: var(--space-sm);
  border: var(--rule-width) solid var(--border-subtle);
  background: var(--color-paper);
  color: var(--text-primary);
  transition:
    background-color var(--dur-short) var(--ease-out),
    border-color var(--dur-short) var(--ease-out);
}

.visa-results-board-link svg,
.visa-featured-primary svg,
.visa-featured-secondary svg {
  width: 1rem;
  height: 1rem;
  flex: 0 0 auto;
}

.visa-results-board-link:focus-visible,
.visa-featured-primary:focus-visible,
.visa-featured-secondary:focus-visible,
.visa-results-minimal-empty a:focus-visible,
.visa-results-state-action:focus-visible {
  outline: 3px solid var(--color-ink);
  outline-offset: 3px;
}

.visa-results-board-link:active,
.visa-featured-primary:active,
.visa-featured-secondary:active,
.visa-results-minimal-empty a:active,
.visa-results-state-action:active {
  transform: translateY(1px);
}

.visa-results-board-link[aria-disabled="true"],
.visa-featured-primary[aria-disabled="true"],
.visa-featured-secondary[aria-disabled="true"],
.visa-results-state-action:disabled {
  cursor: not-allowed;
  opacity: 0.55;
  transform: none;
}

.visa-results-note {
  display: inline-flex;
  width: fit-content;
  align-items: center;
  gap: var(--space-2xs);
  color: var(--text-muted);
  font-size: 0.75rem;
  line-height: 1.5;
}

.visa-results-note svg {
  flex: 0 0 auto;
  width: 0.875rem;
  height: 0.875rem;
}

.visa-featured-list {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: var(--space-sm);
}

.visa-featured-card {
  display: grid;
  grid-template-rows: auto auto 1fr auto;
  gap: var(--space-sm);
  min-width: 0;
  padding: var(--space-md);
  border: var(--rule-width) solid var(--border-subtle);
  border-radius: var(--radius-card);
  background: var(--color-paper);
  color: var(--text-primary);
  box-shadow: var(--shadow-sm);
  transition:
    background-color var(--dur-short) var(--ease-out),
    border-color var(--dur-short) var(--ease-out),
    box-shadow var(--dur-short) var(--ease-out),
    transform var(--dur-short) var(--ease-out);
}

.visa-featured-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-xs);
  min-width: 0;
}

.visa-featured-mark {
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  width: 2.75rem;
  height: 2.75rem;
  border-radius: var(--radius-input);
  background: var(--color-paper-3);
  color: var(--text-primary);
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.visa-featured-signal {
  display: inline-flex;
  align-items: center;
  gap: var(--space-3xs);
  min-height: 1.75rem;
  padding-inline: var(--space-2xs);
  border-radius: var(--radius-pill);
  background: var(--accent-green-soft);
  color: var(--accent-green);
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.01em;
  white-space: nowrap;
}

.visa-featured-signal svg {
  width: 0.875rem;
  height: 0.875rem;
}

.visa-featured-copy {
  display: grid;
  min-width: 0;
  gap: var(--space-3xs);
}

.visa-featured-copy h3 {
  color: var(--text-primary);
  font-family: var(--font-display);
  font-size: clamp(1.0625rem, 0.8vw + 0.9rem, 1.25rem);
  font-style: normal;
  font-weight: 700;
  letter-spacing: -0.025em;
  line-height: 1.25;
}

.visa-featured-location {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: var(--space-3xs);
  color: var(--text-muted);
  font-size: 0.8125rem;
  line-height: 1.5;
}

.visa-featured-location svg {
  flex: 0 0 auto;
  width: 0.9375rem;
  height: 0.9375rem;
}

.visa-featured-location span {
  min-width: 0;
  overflow-wrap: anywhere;
}

.visa-featured-count {
  display: grid;
  gap: var(--space-3xs);
  min-width: 0;
  padding: var(--space-xs) var(--space-sm);
  border-radius: var(--radius-input);
  background: var(--color-paper-2);
  border: var(--rule-width) solid var(--border-subtle);
}

.visa-featured-count strong {
  color: var(--text-primary);
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1;
}

.visa-featured-count span {
  color: var(--text-secondary);
  font-size: 0.75rem;
  font-weight: 600;
  line-height: 1.4;
}

.visa-featured-actions {
  display: grid;
  gap: var(--space-2xs);
  margin-top: auto;
}

.visa-featured-primary {
  width: 100%;
  padding-inline: var(--space-md);
  background: var(--accent-primary);
  color: var(--text-on-accent);
  box-shadow: var(--shadow-button);
  transition:
    background-color var(--dur-short) var(--ease-out),
    transform 100ms var(--ease-out),
    box-shadow 100ms var(--ease-out);
}

.visa-featured-primary:active {
  box-shadow: var(--shadow-button-pressed);
}

.visa-featured-secondary {
  width: 100%;
  padding-inline: var(--space-md);
  border: var(--rule-width) solid var(--border-subtle);
  background: var(--color-paper);
  color: var(--text-primary);
  transition:
    background-color var(--dur-short) var(--ease-out),
    border-color var(--dur-short) var(--ease-out);
}

.visa-results-minimal-empty {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-xs);
  padding-block: var(--space-xs);
  border-block: var(--rule-width) solid var(--border-subtle);
  color: var(--text-secondary);
  font-size: 0.8125rem;
}

.visa-results-minimal-empty a {
  min-height: 2.75rem;
  display: inline-flex;
  align-items: center;
  color: var(--text-primary);
  font-weight: 700;
  white-space: nowrap;
}

.visa-results-state {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: var(--space-sm);
  align-items: center;
  padding: var(--space-md);
  border: var(--rule-width) solid var(--color-rule);
  border-radius: var(--radius-card);
  background: var(--color-paper);
  color: var(--text-primary);
  box-shadow: var(--shadow-card);
}

.visa-results-state h3 {
  font-family: var(--font-display);
  font-size: 1rem;
  font-style: normal;
  font-weight: 700;
}

.visa-results-state p {
  margin-top: var(--space-3xs);
  color: var(--text-secondary);
  font-size: 0.8125rem;
  line-height: 1.6;
}

.visa-results-state-action {
  grid-column: 1 / -1;
  display: inline-flex;
  width: fit-content;
  min-height: 2.75rem;
  align-items: center;
  justify-content: center;
  padding-inline: var(--space-md);
  white-space: nowrap;
  font-size: 0.875rem;
  font-weight: 700;
  cursor: pointer;
}

.visa-featured-skeleton {
  min-height: 14rem;
  box-shadow: none;
}

.visa-featured-skeleton span {
  display: block;
  height: 0.75rem;
  border-radius: var(--radius-pill);
  background: var(--color-paper-3);
  animation: visa-featured-loading 1.2s var(--ease-snap) infinite alternate;
}

.visa-featured-skeleton span:nth-child(1) {
  width: 2.75rem;
  height: 2.75rem;
  border-radius: var(--radius-input);
}

.visa-featured-skeleton span:nth-child(2) {
  width: 68%;
}

.visa-featured-skeleton span:nth-child(3) {
  width: 42%;
  height: 3rem;
  border-radius: var(--radius-input);
}

.visa-featured-skeleton span:nth-child(4) {
  width: 100%;
  height: 2.75rem;
  border-radius: var(--radius-button);
}

@keyframes visa-featured-loading {
  from {
    opacity: 0.45;
  }
  to {
    opacity: 1;
  }
}

@media (hover: hover) and (pointer: fine) {
  .visa-results-board-link:hover {
    border-color: var(--color-rule);
    background: var(--color-paper-2);
  }

  .visa-featured-card:hover {
    border-color: var(--color-rule);
    background: var(--color-paper);
    box-shadow: var(--shadow-card);
    transform: translateY(-2px);
  }

  .visa-featured-primary:hover {
    background: var(--accent-primary-hover);
    box-shadow: var(--shadow-button-hover);
  }

  .visa-featured-secondary:hover {
    border-color: var(--color-rule);
    background: var(--color-paper-2);
  }
}

@media (min-width: 40rem) {
  .visa-results-head {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .visa-featured-list {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .visa-results-state {
    grid-template-columns: auto minmax(0, 1fr) auto;
  }

  .visa-results-state-action {
    grid-column: auto;
  }
}

